// Every grade level the app offers, in order. Dashboards, registration and section
// management all build their grade lists from this, so adding a grade above is enough.
const GRADE_LEVELS = Object.keys(GRADES).map(Number).sort((a,b) => a-b);
// Junior High (7–10) and Senior High (11–12), used to group grades in the dashboards.
function gradeBand(g){ return Number(g) >= 11 ? 'Senior High School' : 'Junior High School'; }
// Grades whose items come from the teacher's instrument with one purpose-built scene per
// item (grade7-scenes.js, shs-scenes.js) and the centred question flow.
function isSceneGrade(g){ return !!(GRADES[g] && GRADES[g].itemScenes); }
